insert into public.lessons (level_id, slug, title, description, category, duration_minutes, sort_order, is_published)
select levels.id, lesson.slug, lesson.title, lesson.description, lesson.category, lesson.duration_minutes,
  coalesce((select max(existing.sort_order) from public.lessons as existing where existing.level_id = levels.id), 0) + lesson.level_order,
  false
from (values
    ('pdf-b2-120-grammar-vocabulary', 'B2', 'B2: gramática e vocabulário em contexto', 'Tempos verbais, condicionais, reported speech, voz passiva, vocabulário e combinações comuns. Rascunho importado do caderno Upper-Intermediate; revisar antes de publicar.', 'Gramática', 18, 1),
    ('pdf-b2-120-grammar-expressions', 'B2', 'B2: estruturas e expressões', 'Modais, inversões, condicionais, conectores e expressões de uso frequente. Rascunho importado do caderno Upper-Intermediate; revisar antes de publicar.', 'Gramática', 18, 2),
    ('pdf-b2-120-phrasal-collocations', 'B2', 'B2: phrasal verbs e collocations', 'Phrasal verbs, vocabulário, preposições e collocations em contexto. Rascunho importado do caderno Upper-Intermediate; revisar antes de publicar.', 'Vocabulário', 18, 3),
    ('pdf-b2-120-sentence-completion', 'B2', 'B2: completar frases', 'Prática de formas verbais, preposições, condicionais e expressões sem alternativas. Rascunho importado do caderno Upper-Intermediate; revisar antes de publicar.', 'Escrita', 18, 4)
) as lesson(slug, level_code, title, description, category, duration_minutes, level_order)
join public.languages on languages.code = 'en'
join public.language_levels as levels on levels.language_id = languages.id and levels.code = lesson.level_code
on conflict (slug) do nothing;

